const cleared = inputs.taxedSettlement.map((t) => {
  const netClearing = t.gatewayNet - t.holdbackAmount + t.pph23Withholding;
  return {
    ref: t.ref,
    netClearing,
    grossDiff: t.grossDiff,
    isCompliant: t.isCompliant,
  };
});
return { clearedRecords: cleared };
```

